"""
wMBus MQTT Bridge — translations and localisation helpers.

All user-visible strings live here.  webui.py imports:
    from i18n import I18N, SOURCE_TEXT, LOCALIZE_EXACT_KEYS, tr, localize_html, lang_switcher

To add a language: add a new key block inside I18N with the same keys as "en".
To add a new UI string:
  1. Add the key to I18N for every language.
  2. Add the key to LOCALIZE_EXACT_KEYS.
  3. Add the English source string to SOURCE_TEXT (used for in-place HTML replacement).
"""
from __future__ import annotations
import re

SUPPORTED_LANGS = {"en", "de", "cs", "sk", "pl"}
DEFAULT_LANG    = "en"
LANG_COOKIE     = "wmbus_lang"

