def tr_phase(lang: str, phase: str, table: dict) -> str:
    lang = lang if lang in SUPPORTED_LANGS else DEFAULT_LANG
    return table.get(lang, table["en"]).get(phase, table["en"].get(phase, ""))


def tr_detail(lang: str, key: str) -> str:
    lang = lang if lang in SUPPORTED_LANGS else DEFAULT_LANG
    return SEARCH_DETAIL_LABELS.get(lang, SEARCH_DETAIL_LABELS["en"]).get(key, key)
